from __future__ import annotations

import re
import shutil
import sys
import unittest
import uuid
from pathlib import Path
from unittest.mock import patch


APP_ROOT = Path(__file__).resolve().parents[2]
if str(APP_ROOT) not in sys.path:
    sys.path.insert(0, str(APP_ROOT))

from scripts import verificar_dependencias  # noqa: E402


LOCK_DE_EXEMPLO = """\
# This file was autogenerated by uv via the following command:
#    uv pip compile requirements.txt
absl-py==2.5.0 \
    --hash=sha256:0c996f25c0490700fadabe6351630f6111534fa0ae252cc6d2014ea3b141135f
    # via ortools
uvicorn[standard]==0.46.0 \
    --hash=sha256:9a6cea6e60b17ebe0a44c5cc636d94f09bd66142c1cd7d8b4cd731c4917a15f6
    # via
    #   fastapi
python-dateutil==2.9.0.post0
"""


class WorkspaceTestCase(unittest.TestCase):
    def setUp(self) -> None:
        self.workspace = (
            Path(__file__).resolve().parent / f".release-scripts-{uuid.uuid4().hex}"
        )
        self.workspace.mkdir()
        self.addCleanup(shutil.rmtree, self.workspace, True)

    def escrever_travas(self, conteudo: str) -> Path:
        caminho = self.workspace / "requirements.lock"
        caminho.write_text(conteudo, encoding="utf-8")
        return caminho


class LeituraDasTravasTests(WorkspaceTestCase):
    def test_le_nome_e_versao_ignorando_hashes_e_comentarios(self) -> None:
        caminho = self.escrever_travas(LOCK_DE_EXEMPLO)

        travadas = verificar_dependencias.dependencias_travadas(caminho)

        self.assertEqual(
            travadas,
            [
                ("absl-py", "2.5.0"),
                ("uvicorn", "0.46.0"),
                ("python-dateutil", "2.9.0.post0"),
            ],
        )

    def test_arquivo_real_cobre_as_dependencias_diretas(self) -> None:
        travadas = dict(
            verificar_dependencias.dependencias_travadas(
                verificar_dependencias.LOCK_FILE
            )
        )

        diretas = re.findall(
            r"^([A-Za-z0-9._-]+)(?:\[[^\]]*\])?==",
            (APP_ROOT / "requirements.txt").read_text(encoding="utf-8"),
            flags=re.MULTILINE,
        )
        self.assertTrue(diretas)
        for nome in diretas:
            self.assertIn(nome, travadas)


class ConferenciaTests(unittest.TestCase):
    def test_separa_ausentes_de_divergentes(self) -> None:
        def versao_falsa(nome: str) -> str:
            if nome == "ausente":
                raise verificar_dependencias.PackageNotFoundError(nome)
            return "1.0.0"

        with patch.object(verificar_dependencias, "version", versao_falsa):
            ausentes, divergentes = verificar_dependencias.conferir(
                [("ausente", "2.0.0"), ("igual", "1.0.0"), ("divergente", "3.0.0")]
            )

        self.assertEqual(ausentes, ["ausente"])
        self.assertEqual(divergentes, [("divergente", "1.0.0", "3.0.0")])


class EnumeracaoTests(unittest.TestCase):
    def test_lista_curta_sai_inteira(self) -> None:
        self.assertEqual(verificar_dependencias.enumerar(["a", "b"]), "a, b")

    def test_lista_longa_e_resumida(self) -> None:
        limite = verificar_dependencias.MAXIMO_LISTADO
        nomes = [f"pacote{indice}" for indice in range(limite + 3)]

        resumo = verificar_dependencias.enumerar(nomes)

        self.assertTrue(resumo.endswith("e mais 3"))
        self.assertIn(nomes[limite - 1], resumo)
        self.assertNotIn(nomes[limite], resumo)


class CodigosDeSaidaTests(WorkspaceTestCase):
    def executar(self, *argumentos: str) -> int:
        return verificar_dependencias.main(["--silencioso", *argumentos])

    def test_ambiente_completo_devolve_zero(self) -> None:
        instalada = verificar_dependencias.version("fastapi")
        caminho = self.escrever_travas(f"fastapi=={instalada}\n")

        self.assertEqual(
            self.executar("--travas", str(caminho)), verificar_dependencias.CODIGO_OK
        )

    def test_dependencia_ausente_devolve_um(self) -> None:
        caminho = self.escrever_travas("pacote-que-nao-existe==1.0.0\n")

        self.assertEqual(
            self.executar("--travas", str(caminho)),
            verificar_dependencias.CODIGO_DEPENDENCIAS_AUSENTES,
        )

    def test_versao_divergente_devolve_um(self) -> None:
        caminho = self.escrever_travas("fastapi==0.0.1\n")

        self.assertEqual(
            self.executar("--travas", str(caminho)),
            verificar_dependencias.CODIGO_DEPENDENCIAS_AUSENTES,
        )

    def test_travas_sem_dependencias_devolvem_erro(self) -> None:
        caminho = self.escrever_travas("# apenas comentarios\n")

        self.assertEqual(
            self.executar("--travas", str(caminho)), verificar_dependencias.CODIGO_ERRO
        )

    def test_travas_ilegiveis_devolvem_erro(self) -> None:
        self.assertEqual(
            self.executar("--travas", str(self.workspace / "inexistente.lock")),
            verificar_dependencias.CODIGO_ERRO,
        )

    def test_interpretador_nao_homologado_devolve_dois(self) -> None:
        with patch.object(
            verificar_dependencias, "interpretador_homologado", return_value=False
        ):
            self.assertEqual(
                self.executar(), verificar_dependencias.CODIGO_PYTHON_INCOMPATIVEL
            )
            self.assertEqual(
                self.executar("--somente-interpretador"),
                verificar_dependencias.CODIGO_PYTHON_INCOMPATIVEL,
            )

    def test_somente_interpretador_nao_confere_pacotes(self) -> None:
        with patch.object(
            verificar_dependencias, "interpretador_homologado", return_value=True
        ), patch.object(verificar_dependencias, "dependencias_travadas") as leitura:
            self.assertEqual(
                self.executar("--somente-interpretador"),
                verificar_dependencias.CODIGO_OK,
            )

        leitura.assert_not_called()


if __name__ == "__main__":
    unittest.main()
